<template><div v-loading="loading"><div class="metric-grid"><el-card v-for="m in metrics" :key="m.label" shadow="never" @click="$router.push(m.to)"><span>{{m.label}}</span><strong>{{m.value}}</strong><small>{{m.hint}}</small></el-card></div><div class="quality-grid"><el-card shadow="never"><template #header><div class="head"><b>最近测试报告</b><el-button link type="primary" @click="$router.push(`/report?project_id=${projectId}`)">查看全部</el-button></div></template><el-table :data="reports"><el-table-column label="运行" min-width="180"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/report/${row.test_run_id||row.id}`)">{{row.name||row.source_ref||row.test_run_id}}</el-button></template></el-table-column><el-table-column prop="quality_score" label="评分" width="80"/><el-table-column label="门禁" width="90"><template #default="{row}"><el-tag :type="row.gate_passed?'success':'danger'">{{row.gate_passed?'通过':'未通过'}}</el-tag></template></el-table-column><el-table-column label="时间" width="170"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column></el-table><el-empty v-if="!reports.length" description="暂无测试报告" :image-size="55"/></el-card><el-card shadow="never"><template #header><div class="head"><b>最近缺陷</b><el-button link type="primary" @click="$router.push(`/defects?project_id=${projectId}`)">进入缺陷中心</el-button></div></template><div v-for="d in defects" :key="d.id" class="defect"><el-tag :type="d.severity==='P0'?'danger':d.severity==='P1'?'warning':'info'">{{d.severity}}</el-tag><span>{{d.title}}</span><small>{{d.status}}</small></div><el-empty v-if="!defects.length" description="暂无缺陷" :image-size="55"/></el-card></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{defectsApi,reportApi,trendApi}from'@/api';const projectId=String(useRoute().params.id),loading=ref(false),reports=ref<any[]>([]),defects=ref<any[]>([]),summary=ref<any>({});const metrics=computed(()=>[{label:'质量评分',value:summary.value.quality_score??reports.value[0]?.quality_score??'—',hint:'最近一次质量评估',to:`/quality-trend?project_id=${projectId}`},{label:'测试通过率',value:summary.value.pass_rate!=null?`${summary.value.pass_rate}%`:'—',hint:'项目运行趋势',to:`/quality-trend?project_id=${projectId}`},{label:'待处理缺陷',value:summary.value.open_defects??defects.value.length,hint:'需要跟进的问题',to:`/defects?project_id=${projectId}`},{label:'测试报告',value:reports.value.length,hint:'当前显示最近记录',to:`/report?project_id=${projectId}`}]);function formatTime(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}onMounted(async()=>{loading.value=true;try{const[a,b,c]:any=await Promise.allSettled([reportApi.getList({project_id:projectId,page:1,page_size:5}),defectsApi.list({project_id:projectId,page:1,page_size:6}),trendApi.getSummary({project_id:projectId})]);if(a.status==='fulfilled')reports.value=a.value?.data?.list||a.value?.data?.items||[];if(b.status==='fulfilled')defects.value=b.value?.data?.list||b.value?.data?.items||[];if(c.status==='fulfilled')summary.value=c.value?.data||{}}finally{loading.value=false}})</script>
<style scoped>.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}.metric-grid .el-card{cursor:pointer}.metric-grid span,.metric-grid small{display:block;color:var(--app-text-secondary)}.metric-grid strong{display:block;font-size:26px;margin:8px 0}.quality-grid{display:grid;grid-template-columns:2fr 1fr;gap:14px}.head{display:flex;justify-content:space-between;align-items:center}.defect{display:grid;grid-template-columns:45px 1fr auto;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid var(--app-border-base)}.defect small{color:var(--app-text-secondary)}@media(max-width:900px){.metric-grid{grid-template-columns:repeat(2,1fr)}.quality-grid{grid-template-columns:1fr}}</style>
